11	/* !
12	 * \file add_tpipe_tque.asc
13	 * \brief 基于TPipe和TQue的Add向量加法样例，演示按核切分输入数据，
14	 *        并通过队列完成GM到UB搬入、UB内向量加法和结果写回GM的完整流程。
15	 */
16	#include "acl/acl.h"
17	#include "kernel_operator.h"
18	#include "data_utils.h"
19	
20	__global__ __vector__ void add_custom(__gm__ uint8_t* x, __gm__ uint8_t* y, __gm__ uint8_t* z, uint32_t totalLength)
21	{
22	    AscendC::TPipe pipe;
23	    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueueX;
24	    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueueY;
25	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueueZ;
26	    AscendC::GlobalTensor<float> xGm;
27	    AscendC::GlobalTensor<float> yGm;
28	    AscendC::GlobalTensor<float> zGm;
29	
30	    // totalLength 表示全局输入长度；GetBlockNum() 返回本次启动的核数，
31	    // 这里按核数均分每个 block 的处理区间。
32	    uint32_t blockLength = totalLength / AscendC::GetBlockNum();
33	    // 根据 block_idx 计算当前核在 GM 中的起始地址，确保各核访问互不重叠的数据分片。
34	    xGm.SetGlobalBuffer((__gm__ float*)x + blockLength * AscendC::GetBlockIdx(), blockLength);
35	    yGm.SetGlobalBuffer((__gm__ float*)y + blockLength * AscendC::GetBlockIdx(), blockLength);
36	    zGm.SetGlobalBuffer((__gm__ float*)z + blockLength * AscendC::GetBlockIdx(), blockLength);
37	    // 为输入和输出队列申请与 blockLength 对应的 UB 缓冲，保持 TPipe/TQue 的编程范式。
38	    pipe.InitBuffer(inQueueX, 1, blockLength * sizeof(float));
39	    pipe.InitBuffer(inQueueY, 1, blockLength * sizeof(float));
40	    pipe.InitBuffer(outQueueZ, 1, blockLength * sizeof(float));
41	
42	    // 使用 DataCopy 将输入从 GM 搬运到 UB，并通过 EnQue 将 LocalTensor 入队，供后续计算阶段 DeQue 取用。
43	    AscendC::LocalTensor<float> xLocal = inQueueX.AllocTensor<float>();
44	    AscendC::LocalTensor<float> yLocal = inQueueY.AllocTensor<float>();
45	    AscendC::DataCopy(xLocal, xGm, blockLength);
46	    AscendC::DataCopy(yLocal, yGm, blockLength);
47	    inQueueX.EnQue(xLocal);
48	    inQueueY.EnQue(yLocal);
49	
50	    // DeQue 取出输入张量，在 UB 内执行 Add，并将结果 EnQue 到输出队列，供后续写回 GM。
51	    xLocal = inQueueX.DeQue<float>();
52	    yLocal = inQueueY.DeQue<float>();
53	    AscendC::LocalTensor<float> zLocal = outQueueZ.AllocTensor<float>();
54	    AscendC::Add(zLocal, xLocal, yLocal, blockLength);
55	    outQueueZ.EnQue<float>(zLocal);
56	    inQueueX.FreeTensor(xLocal);
57	    inQueueY.FreeTensor(yLocal);
58	
59	    // 从输出队列取出结果，并写回当前核负责的 GM 分片。
60	    zLocal = outQueueZ.DeQue<float>();
61	    AscendC::DataCopy(zGm, zLocal, blockLength);
62	    outQueueZ.FreeTensor(zLocal);
63	}
64	
65	int32_t main(int32_t argc, char* argv[])
66	{
67	    // 启动 8 个核并行处理，每个核负责总长度的 1/8。
68	    uint32_t numBlocks = 8;
69	    constexpr uint32_t totalLength = 8 * 2048;
70	    size_t inputByteSize = totalLength * sizeof(float);
71	    size_t outputByteSize = totalLength * sizeof(float);
72	    uint8_t* xHost = nullptr;
73	    uint8_t* yHost = nullptr;
74	    uint8_t* zHost = nullptr;
75	    uint8_t* xDevice = nullptr;
76	    uint8_t* yDevice = nullptr;
77	    uint8_t* zDevice = nullptr;
78	
79	    aclInit(nullptr);
80	    int32_t deviceId = 0;
81	    aclrtSetDevice(deviceId);
82	    aclrtStream stream = nullptr;
83	    aclrtCreateStream(&stream);
84	
85	    aclrtMallocHost((void**)(&xHost), inputByteSize);
86	    aclrtMallocHost((void**)(&yHost), inputByteSize);
87	    aclrtMallocHost((void**)(&zHost), outputByteSize);
88	    aclrtMalloc((void**)&xDevice, inputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
89	    aclrtMalloc((void**)&yDevice, inputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
90	    aclrtMalloc((void**)&zDevice, outputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
91	
92	    ReadFile("./input/input_x.bin", inputByteSize, xHost, inputByteSize);
93	    ReadFile("./input/input_y.bin", inputByteSize, yHost, inputByteSize);
94	    aclrtMemcpy(xDevice, inputByteSize, xHost, inputByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
95	    aclrtMemcpy(yDevice, inputByteSize, yHost, inputByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
96	
97	    add_custom<<<numBlocks, 0, stream>>>(xDevice, yDevice, zDevice, totalLength);
98	    aclrtSynchronizeStream(stream);
99	    aclrtMemcpy(zHost, outputByteSize, zDevice, outputByteSize, ACL_MEMCPY_DEVICE_TO_HOST);
100	    WriteFile("./output/output.bin", zHost, outputByteSize);
101	
102	    aclrtFree(xDevice);
103	    aclrtFree(yDevice);
104	    aclrtFree(zDevice);
105	    aclrtFreeHost(xHost);
106	    aclrtFreeHost(yHost);
107	    aclrtFreeHost(zHost);
108	
109	    aclrtDestroyStream(stream);
110	    aclrtResetDevice(deviceId);
111	    aclFinalize();
112	
113	    return 0;
114	}
