7	 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	/* !
12	 * \file matmul.asc
13	 * \brief Static matmul based on tensor_api
14	 */
15	
16	#include "acl/acl.h"
17	#include "tensor_api/tensor.h"
18	#include "basic_api/kernel_basic_intf.h"
19	#include "basic_api/kernel_operator_block_sync_intf.h"
20	#include "data_utils.h"
21	
22	template <uint32_t M, uint32_t K, uint32_t N, uint32_t singleCoreM, uint32_t baseM, uint32_t baseK, uint32_t baseN>
23	__global__ __cube__ void matmul_custom(__gm__ half* a, __gm__ half* b, __gm__ half* c)
24	{
25	    AscendC::InitSocState();
26	    using namespace AscendC::Te;
27	
28	    // Split the output matrix by M and N tiles across Cube cores.
29	    constexpr uint32_t mIter = M / singleCoreM;
30	    uint32_t mIterIdx = AscendC::GetBlockIdx() % mIter;
31	    uint32_t nIterIdx = AscendC::GetBlockIdx() / mIter;
32	
33	    // Create GM tensors and slice the tile handled by the current core.
34	    auto gmA = MakeTensor(MakeMemPtr(a), MakeFrameLayout<NDExtLayoutPtn>(M, K));
35	    auto gmB = MakeTensor(MakeMemPtr(b), MakeFrameLayout<NDExtLayoutPtn>(K, N));
36	    auto gmC = MakeTensor(MakeMemPtr(c), MakeFrameLayout<NDExtLayoutPtn>(M, N));
37	
38	    auto globalA = gmA.Slice(MakeCoord(mIterIdx * singleCoreM, 0), MakeShape(baseM, K));
39	    auto globalB = gmB.Slice(MakeCoord(0, nIterIdx * baseN), MakeShape(K, baseN));
40	    auto globalC = gmC.Slice(MakeCoord(mIterIdx * singleCoreM, nIterIdx * baseN), MakeShape(baseM, baseN));
41	
42	    auto l1ALayout = MakeFrameLayout<NZLayoutPtn>(baseM, K);
43	    auto l1BLayout = MakeFrameLayout<NZLayoutPtn>(K, baseN);
44	    auto l0ALayout = MakeFrameLayout<NZLayoutPtn>(baseM, baseK);
45	    auto l0BLayout = MakeFrameLayout<ZNLayoutPtn>(baseK, baseN);
46	    auto l0CLayout = MakeFrameLayout<NZLayoutPtn>(baseM, baseN);
47	
48	    __cbuf__ half l1ABuf[baseM * K];
49	    __cbuf__ half l1BBuf[K * baseN];
50	    __ca__ half l0ABuf[baseM * baseK];
51	    __cb__ half l0BBuf[baseK * baseN];
52	    __cc__ float l0CBuf[baseM * baseN];
53	
54	    auto l1ATensor = MakeTensor(MakeMemPtr(l1ABuf), l1ALayout);
55	    auto l1BTensor = MakeTensor(MakeMemPtr(l1BBuf), l1BLayout);
56	    auto l0ATensor = MakeTensor(MakeMemPtr(l0ABuf), l0ALayout);
57	    auto l0BTensor = MakeTensor(MakeMemPtr(l0BBuf), l0BLayout);
58	    auto l0CTensor = MakeTensor(MakeMemPtr(l0CBuf), l0CLayout);
59	
60	    auto copyGM2L1Atom = MakeCopy(CopyGM2L1{}, CopyGM2L1TraitDefault{});
61	    auto copyL12L0AAtom = MakeCopy(CopyL12L0A{}, CopyL12L0ATraitDefault{});
62	    auto copyL12L0BAtom = MakeCopy(CopyL12L0B{}, CopyL12L0BTraitDefault{});
63	    auto copyL0C2GMAtom = MakeCopy(CopyL0C2GM{}, CopyL0C2GMTraitDefault{});
64	    auto mmadAtom = MakeMmad(MmadOperation{}, MmadTraitDefault{});
65	
66	    constexpr uint32_t kLoop = K / baseK;
67	    constexpr uint32_t L1_Index = 0;
68	    constexpr uint32_t L0_Index = 1;
69	    constexpr uint32_t L0C_Index = 2;
70	
71	    AscendC::Mutex::Lock<PIPE_M>(L0C_Index);
72	    // Move the current core's full A/B tiles from GM to L1 once.
73	    AscendC::Mutex::Lock<PIPE_MTE2>(L1_Index);
74	    Copy(copyGM2L1Atom, l1ATensor, globalA);
75	    Copy(copyGM2L1Atom, l1BTensor, globalB);
76	    AscendC::Mutex::Unlock<PIPE_MTE2>(L1_Index);
77	    AscendC::Mutex::Lock<PIPE_MTE1>(L1_Index);
78	
79	    for (uint32_t kIter = 0; kIter < kLoop; ++kIter) {
80	        // Load one K tile from L1 to L0, then accumulate it into L0C.
81	        AscendC::Mutex::Lock<PIPE_MTE1>(L0_Index);
82	        Copy(copyL12L0AAtom, l0ATensor, l1ATensor.Slice(MakeCoord(0, kIter * baseK), MakeShape(baseM, baseK)));
83	        Copy(copyL12L0BAtom, l0BTensor, l1BTensor.Slice(MakeCoord(kIter * baseK, 0), MakeShape(baseK, baseN)));
84	        AscendC::Mutex::Unlock<PIPE_MTE1>(L0_Index);
85	        AscendC::Mutex::Lock<PIPE_M>(L0_Index);
86	
87	        MmadParams para{baseM, baseN, baseK, 0, kIter == 0};
88	        Mmad(mmadAtom.with(para), l0CTensor, l0ATensor, l0BTensor);
89	
90	        AscendC::Mutex::Unlock<PIPE_M>(L0_Index);
91	    }
92	    AscendC::Mutex::Unlock<PIPE_MTE1>(L1_Index);
93	    AscendC::Mutex::Unlock<PIPE_M>(L0C_Index);
94	    // Store the completed output tile from L0C back to GM.
95	    AscendC::Mutex::Lock<PIPE_FIX>(L0C_Index);
96	    Copy(copyL0C2GMAtom, globalC, l0CTensor);
97	    AscendC::Mutex::Unlock<PIPE_FIX>(L0C_Index);
98	    AscendC::PipeBarrier<PIPE_ALL>();
99	}
100	
101	int32_t main(int32_t argc, char* argv[])
102	{
103	    // matmul参数
104	    constexpr uint32_t M = 512;
105	    constexpr uint32_t K = 512;
106	    constexpr uint32_t N = 1024;
107	    // 矩阵乘执行单元Tile参数
108	    constexpr uint32_t baseM = 128;
109	    constexpr uint32_t baseK = 64;
110	    constexpr uint32_t baseN = 256;
111	
112	    size_t aFileSize = M * K * sizeof(half);
113	    size_t bFileSize = K * N * sizeof(half);
114	    size_t cFileSize = M * N * sizeof(half);
115	    uint32_t numBlocks = 16;
116	
117	    aclInit(nullptr);
118	    int32_t deviceId = 0;
119	    aclrtSetDevice(deviceId);
120	    aclrtStream stream = nullptr;
121	    aclrtCreateStream(&stream);
122	
123	    half* aHost;
124	    half* aDevice;
125	    aclrtMallocHost((void**)(&aHost), aFileSize);
126	    aclrtMalloc((void**)&aDevice, aFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
127	    ReadFile("./input/x1_gm.bin", aFileSize, aHost, aFileSize);
128	    aclrtMemcpy(aDevice, aFileSize, aHost, aFileSize, ACL_MEMCPY_HOST_TO_DEVICE);
129	
130	    half* bHost;
131	    half* bDevice;
132	    aclrtMallocHost((void**)(&bHost), bFileSize);
133	    aclrtMalloc((void**)&bDevice, bFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
134	    ReadFile("./input/x2_gm.bin", bFileSize, bHost, bFileSize);
135	    aclrtMemcpy(bDevice, bFileSize, bHost, bFileSize, ACL_MEMCPY_HOST_TO_DEVICE);
136	
137	    half* cHost;
138	    half* cDevice;
139	    aclrtMallocHost((void**)(&cHost), cFileSize);
140	    aclrtMalloc((void**)&cDevice, cFileSize, ACL_MEM_MALLOC_HUGE_FIRST);
141	
142	    matmul_custom<M, K, N, baseM, baseM, baseK, baseN><<<numBlocks, 0, stream>>>(aDevice, bDevice, cDevice);
143	    aclrtSynchronizeStream(stream);
144	
145	    aclrtMemcpy(cHost, cFileSize, cDevice, cFileSize, ACL_MEMCPY_DEVICE_TO_HOST);
146	    WriteFile("./output/output.bin", cHost, cFileSize);
147	
148	    aclrtFree(aDevice);
149	    aclrtFreeHost(aHost);
150	    aclrtFree(bDevice);
151	    aclrtFreeHost(bHost);
152	    aclrtFree(cDevice);
153	    aclrtFreeHost(cHost);
154	
155	    aclrtDestroyStream(stream);
156	    aclrtResetDevice(deviceId);
157	    aclFinalize();
158	    return 0;
159	}
